add_filter( 'post_row_actions', 'perfectpixel_duplicate_row_action', 20, 2 );
add_filter( 'page_row_actions', 'perfectpixel_duplicate_row_action', 20, 2 );
add_action( 'admin_bar_menu', 'perfectpixel_duplicate_admin_bar', 90 );
add_action( 'admin_action_perfectpixel_duplicate_post', 'perfectpixel_duplicate_post_action' );

function perfectpixel_duplicate_allowed( $post ) {
	$post = get_post( $post );
	if ( ! $post || in_array( $post->post_type, array( 'attachment', 'product', 'product_variation', 'shop_order', 'wp_template', 'wp_template_part', 'wp_navigation', 'wp_global_styles' ), true ) ) {
		return false;
	}
	$type = get_post_type_object( $post->post_type );
	return $type && $type->show_ui && current_user_can( 'edit_post', $post->ID ) && current_user_can( $type->cap->create_posts );
}

function perfectpixel_duplicate_url( $post_id ) {
	return wp_nonce_url( admin_url( 'admin.php?action=perfectpixel_duplicate_post&post=' . (int) $post_id ), 'perfectpixel_duplicate_' . (int) $post_id );
}

function perfectpixel_duplicate_row_action( $actions, $post ) {
	if ( perfectpixel_duplicate_allowed( $post ) ) {
		$actions['perfectpixel_duplicate'] = '<a href="' . esc_url( perfectpixel_duplicate_url( $post->ID ) ) . '">Αντιγραφή</a>';
	}
	return $actions;
}

function perfectpixel_duplicate_admin_bar( $wp_admin_bar ) {
	$post_id = 0;
	if ( is_admin() ) {
		$screen = function_exists( 'get_current_screen' ) ? get_current_screen() : null;
		if ( $screen && 'post' === $screen->base && isset( $_GET['post'] ) ) {
			$post_id = absint( $_GET['post'] );
		}
	} elseif ( is_singular() ) {
		$post_id = get_queried_object_id();
	}
	if ( $post_id && perfectpixel_duplicate_allowed( $post_id ) ) {
		$wp_admin_bar->add_node(
			array(
				'id'    => 'perfectpixel-duplicate',
				'title' => 'Αντιγραφή',
				'href'  => perfectpixel_duplicate_url( $post_id ),
			)
		);
	}
}

function perfectpixel_duplicate_post_action() {
	$post_id = isset( $_GET['post'] ) ? absint( $_GET['post'] ) : 0;
	check_admin_referer( 'perfectpixel_duplicate_' . $post_id );
	$post = get_post( $post_id );
	if ( ! $post || ! perfectpixel_duplicate_allowed( $post ) ) {
		wp_die( esc_html__( 'Sorry, you are not allowed to edit this item.' ) );
	}

	$new_id = wp_insert_post(
		wp_slash(
			array(
				'post_type'      => $post->post_type,
				'post_status'    => 'draft',
				'post_title'     => $post->post_title . '{{duplicate_title_suffix}}',
				'post_content'   => $post->post_content,
				'post_excerpt'   => $post->post_excerpt,
				'post_parent'    => $post->post_parent,
				'menu_order'     => $post->menu_order,
				'post_password'  => $post->post_password,
				'comment_status' => $post->comment_status,
				'ping_status'    => $post->ping_status,
				'post_author'    => get_current_user_id(),
			)
		),
		true
	);
	if ( is_wp_error( $new_id ) ) {
		wp_die( esc_html( $new_id->get_error_message() ) );
	}

	foreach ( get_object_taxonomies( $post->post_type ) as $taxonomy ) {
		$terms = wp_get_object_terms( $post->ID, $taxonomy, array( 'fields' => 'ids' ) );
		if ( $terms && ! is_wp_error( $terms ) ) {
			wp_set_object_terms( $new_id, $terms, $taxonomy );
		}
	}

	$skip = array( '_edit_lock', '_edit_last', '_wp_old_slug', '_wp_old_date', '_wp_trash_meta_status', '_wp_trash_meta_time' );
	foreach ( get_post_meta( $post->ID ) as $key => $values ) {
		if ( in_array( $key, $skip, true ) ) {
			continue;
		}
		foreach ( $values as $value ) {
			add_post_meta( $new_id, $key, wp_slash( maybe_unserialize( $value ) ) );
		}
	}

	wp_safe_redirect( admin_url( 'post.php?action=edit&post=' . (int) $new_id ) );
	exit;
}
